    .{ .name = "@abs", .signature = "@abs(value: anytype) anytype", .parameters = &.{
        "value: anytype",
    }, .documentation = "Returns the absolute value of an integer or a floating point number. Uses a dedicated hardware instruction when available. The return type is always an unsigned integer of the same bit width as the operand if the operand is an integer. Unsigned integer operands are supported. The builtin cannot overflow for signed integer operands.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats), [Integers](https://ziglang.org/documentation/0.17.1/#Integers) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats or integers.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#abs)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#abs", .compiler_param_count = 1 },
