    .{ .name = "@addrSpaceCast", .signature = "@addrSpaceCast(ptr: anytype) anytype", .parameters = &.{
        "ptr: anytype",
    }, .documentation = "Converts a pointer from one address space to another. The new address space is inferred based on the result type. Depending on the current target and address spaces, this cast may be a no-op, a complex operation, or illegal. If the cast is legal, then the resulting pointer points to the same memory location as the pointer operand. It is always valid to cast a pointer between the same address spaces.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#addrSpaceCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#addrSpaceCast", .compiler_param_count = 1 },
    .{ .name = "@alignCast", .signature = "@alignCast(ptr: anytype) anytype", .parameters = &.{
        "ptr: anytype",
    }, .documentation = "`ptr` can be `*T`, `?*T`, or `[]T`. Changes the alignment of a pointer. The alignment to use is inferred based on the result type.\n\nA [pointer alignment safety check](https://ziglang.org/documentation/0.17.1/#Incorrect-Pointer-Alignment) is added to the generated code to make sure the pointer is aligned as promised.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#alignCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#alignCast", .compiler_param_count = 1 },
    .{ .name = "@alignOf", .signature = "@alignOf(comptime T: type) comptime_int", .parameters = &.{
        "comptime T: type",
    }, .documentation = "This function returns the number of bytes that this type should be aligned to for the current target to match the C ABI. When the child type of a pointer has this alignment, the alignment can be omitted from the type.\n\n```zig\nconst assert = @import(\"std\").debug.assert;\ncomptime {\n    assert(*u32 == *align(@alignOf(u32)) u32);\n}\n```\n\nThe result is a target-specific compile time constant. It is guaranteed to be less than or equal to [@sizeOf(T)](https://ziglang.org/documentation/0.17.1/#sizeOf).\n\nSee also: [Alignment](https://ziglang.org/documentation/0.17.1/#Alignment)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#alignOf)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#alignOf", .compiler_param_count = 1 },
    .{ .name = "@as", .signature = "@as(comptime T: type, expression) T", .parameters = &.{
        "comptime T: type",
