    .{ .name = "@atomicLoad", .signature = "@atomicLoad(comptime T: type, ptr: *const T, comptime ordering: AtomicOrder) T", .parameters = &.{
        "comptime T: type",
        "ptr: *const T",
        "comptime ordering: AtomicOrder",
    }, .documentation = "This builtin function atomically dereferences a pointer to a `T` and returns the value.\n\n`T` must be a pointer, a `bool`, a float, an integer, an enum, or a packed struct.\n\n`AtomicOrder` can be found with `@import(\"std\").lang.AtomicOrder`.\n\nSee also: [@atomicStore](https://ziglang.org/documentation/0.17.1/#atomicStore), [@atomicRmw](https://ziglang.org/documentation/0.17.1/#atomicRmw), [@cmpxchgWeak](https://ziglang.org/documentation/0.17.1/#cmpxchgWeak), [@cmpxchgStrong](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#atomicLoad)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#atomicLoad", .compiler_param_count = 3 },
    .{ .name = "@atomicRmw", .signature = "@atomicRmw(comptime T: type, ptr: *T, comptime op: AtomicRmwOp, operand: T, comptime ordering: AtomicOrder) T", .parameters = &.{
        "comptime T: type",
        "ptr: *T",
        "comptime op: AtomicRmwOp",
        "operand: T",
        "comptime ordering: AtomicOrder",
    }, .documentation = "This builtin function dereferences a pointer to a `T` and atomically modifies the value and returns the previous value.\n\n`T` must be a pointer, a `bool`, a float, an integer, an enum, or a packed struct.\n\n`AtomicOrder` can be found with `@import(\"std\").lang.AtomicOrder`.\n\n`AtomicRmwOp` can be found with `@import(\"std\").lang.AtomicRmwOp`.\n\nSee also: [@atomicStore](https://ziglang.org/documentation/0.17.1/#atomicStore), [@atomicLoad](https://ziglang.org/documentation/0.17.1/#atomicLoad), [@cmpxchgWeak](https://ziglang.org/documentation/0.17.1/#cmpxchgWeak), [@cmpxchgStrong](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#atomicRmw)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#atomicRmw", .compiler_param_count = 5 },
    .{ .name = "@atomicStore", .signature = "@atomicStore(comptime T: type, ptr: *T, value: T, comptime ordering: AtomicOrder) void", .parameters = &.{
