        "value: T",
        "comptime ordering: AtomicOrder",
    }, .documentation = "This builtin function dereferences a pointer to a `T` and atomically stores the given value.\n\n`T` must be a pointer, a `bool`, a float, an integer, an enum, or a packed struct.\n\n`AtomicOrder` can be found with `@import(\"std\").lang.AtomicOrder`.\n\nSee also: [@atomicLoad](https://ziglang.org/documentation/0.17.1/#atomicLoad), [@atomicRmw](https://ziglang.org/documentation/0.17.1/#atomicRmw), [@cmpxchgWeak](https://ziglang.org/documentation/0.17.1/#cmpxchgWeak), [@cmpxchgStrong](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#atomicStore)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#atomicStore", .compiler_param_count = 4 },
    .{ .name = "@backingInt", .signature = "@backingInt(enum_or_bitpack: T) BackingInt(T)", .parameters = &.{
        "enum_or_bitpack: T",
    }, .documentation = "Converts an [enum](https://ziglang.org/documentation/0.17.1/#enum), a [packed struct](https://ziglang.org/documentation/0.17.1/#packed-struct) or a [packed union](https://ziglang.org/documentation/0.17.1/#packed-union) value to its backing integer.\n\nAlso works with [tagged unions](https://ziglang.org/documentation/0.17.1/#Tagged-union), acting on the active enum tag value.\n\nSee also: [@fromBackingInt](https://ziglang.org/documentation/0.17.1/#fromBackingInt), [@bitCast](https://ziglang.org/documentation/0.17.1/#bitCast)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#backingInt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#backingInt", .compiler_param_count = 1 },
    .{ .name = "@bitCast", .signature = "@bitCast(value: anytype) anytype", .parameters = &.{
        "value: anytype",
    }, .documentation = "Converts a value of one type to another type. The return type is the inferred result type.\n\nAsserts that `@sizeOf(@TypeOf(value)) == @sizeOf(DestType)`.\n\nAsserts that `@typeInfo(DestType) != .pointer`. Use `@ptrCast` or `@ptrFromInt` if you need this.\n\nCan be used for these things for example:\n\n- Convert `f32` to `u32` bits\n- Convert `i32` to `u32` preserving twos complement\n\nWorks at compile-time if `value` is known at compile time. It's a compile error to bitcast a value of undefined layout; this means that, besides the restriction from types which possess dedicated casting builtins (pointers, error sets), bare structs, error unions, slices, optionals, and any other type without a well-defined memory layout, also cannot be used in this operation.\n\nAttempting to convert an integer with no corresponding tag value to an `enum` invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\nSee also: [@ptrCast](https://ziglang.org/documentation/0.17.1/#ptrCast), [@intFromPtr](https://ziglang.org/documentation/0.17.1/#intFromPtr), [@ptrFromInt](https://ziglang.org/documentation/0.17.1/#ptrFromInt), [@errorCast](https://ziglang.org/documentation/0.17.1/#errorCast), [@intFromError](https://ziglang.org/documentation/0.17.1/#intFromError), [@errorFromInt](https://ziglang.org/documentation/0.17.1/#errorFromInt), [@backingInt](https://ziglang.org/documentation/0.17.1/#backingInt), [@fromBackingInt](https://ziglang.org/documentation/0.17.1/#fromBackingInt)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#bitCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#bitCast", .compiler_param_count = 1 },
    .{ .name = "@bitOffsetOf", .signature = "@bitOffsetOf(comptime T: type, comptime field_name: []const u8) comptime_int", .parameters = &.{
        "comptime T: type",
        "comptime field_name: []const u8",
    }, .documentation = "Returns the bit offset of a field relative to its containing struct.\n\nFor non [packed structs](https://ziglang.org/documentation/0.17.1/#packed-struct), this will always be divisible by `8`. For packed structs, non-byte-aligned fields will share a byte offset, but they will have different bit offsets.\n\nSee also: [@offsetOf](https://ziglang.org/documentation/0.17.1/#offsetOf)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#bitOffsetOf)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#bitOffsetOf", .compiler_param_count = 2 },
    .{ .name = "@bitReverse", .signature = "@bitReverse(integer: anytype) T", .parameters = &.{
        "integer: anytype",
    }, .documentation = "`@TypeOf(anytype)` accepts any integer type or integer vector type.\n\nReverses the bitpattern of an integer value, including the sign bit if applicable.\n\nFor example 0b10110110 (`u8 = 182`, `i8 = -74`) becomes 0b01101101 (`u8 = 109`, `i8 = 109`).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#bitReverse)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#bitReverse", .compiler_param_count = 1 },
    .{ .name = "@bitSizeOf", .signature = "@bitSizeOf(comptime T: type) comptime_int", .parameters = &.{
        "comptime T: type",
    }, .documentation = "This function returns the number of bits it takes to store `T` in memory if the type were a field in a packed struct/union. The result is a target-specific compile time constant.\n\nThis function measures the size at runtime. For types that are disallowed at runtime, such as `comptime_int` and `type`, the result is `0`.\n\nSee also: [@sizeOf](https://ziglang.org/documentation/0.17.1/#sizeOf), [@typeInfo](https://ziglang.org/documentation/0.17.1/#typeInfo)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#bitSizeOf)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#bitSizeOf", .compiler_param_count = 1 },
    .{ .name = "@branchHint", .signature = "@branchHint(hint: BranchHint) void", .parameters = &.{
        "hint: BranchHint",
    }, .documentation = "Hints to the optimizer how likely a given branch of control flow is to be reached.\n\n`BranchHint` can be found with `@import(\"std\").lang.BranchHint`.\n\nThis function is only valid as the first statement in a control flow branch, or the first statement in a function.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#branchHint)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#branchHint", .compiler_param_count = 1 },
    .{ .name = "@breakpoint", .signature = "@breakpoint() void", .parameters = &.{}, .documentation = "This function inserts a platform-specific debug trap instruction which causes debuggers to break there. Unlike for `@trap()`, execution may continue after this point if the program is resumed.\n\nThis function is only valid within function scope.\n\nSee also: [@trap](https://ziglang.org/documentation/0.17.1/#trap)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#breakpoint)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#breakpoint", .compiler_param_count = 0 },
    .{ .name = "@byteSwap", .signature = "@byteSwap(operand: anytype) T", .parameters = &.{
        "operand: anytype",
    }, .documentation = "`@TypeOf(operand)` must be an integer type or an integer vector type with bit count evenly divisible by 8.\n\n`operand` may be an [integer](https://ziglang.org/documentation/0.17.1/#Integers) or [vector](https://ziglang.org/documentation/0.17.1/#Vectors).\n\nSwaps the byte order of the integer. This converts a big endian integer to a little endian integer, and converts a little endian integer to a big endian integer.\n\nNote that for the purposes of memory layout with respect to endianness, the integer type should be related to the number of bytes reported by [@sizeOf](https://ziglang.org/documentation/0.17.1/#sizeOf) bytes. This is demonstrated with `u24`. `@sizeOf(u24) == 4`, which means that a `u24` stored in memory takes 4 bytes, and those 4 bytes are what are swapped on a little vs big endian system. On the other hand, if `T` is specified to be `u24`, then only 3 bytes are reversed.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#byteSwap)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#byteSwap", .compiler_param_count = 1 },
    .{ .name = "@cVaArg", .signature = "@cVaArg(operand: *std.lang.VaList, comptime T: type) T", .parameters = &.{
        "operand: *std.lang.VaList",
        "comptime T: type",
    }, .documentation = "Implements the C macro `va_arg`.\n\nSee also: [@cVaCopy](https://ziglang.org/documentation/0.17.1/#cVaCopy), [@cVaEnd](https://ziglang.org/documentation/0.17.1/#cVaEnd), [@cVaStart](https://ziglang.org/documentation/0.17.1/#cVaStart)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cVaArg)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cVaArg", .compiler_param_count = 2 },
    .{ .name = "@cVaCopy", .signature = "@cVaCopy(src: *std.lang.VaList) std.lang.VaList", .parameters = &.{
        "src: *std.lang.VaList",
    }, .documentation = "Implements the C macro `va_copy`.\n\nSee also: [@cVaArg](https://ziglang.org/documentation/0.17.1/#cVaArg), [@cVaEnd](https://ziglang.org/documentation/0.17.1/#cVaEnd), [@cVaStart](https://ziglang.org/documentation/0.17.1/#cVaStart)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cVaCopy)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cVaCopy", .compiler_param_count = 1 },
    .{ .name = "@cVaEnd", .signature = "@cVaEnd(src: *std.lang.VaList) void", .parameters = &.{
        "src: *std.lang.VaList",
    }, .documentation = "Implements the C macro `va_end`.\n\nSee also: [@cVaArg](https://ziglang.org/documentation/0.17.1/#cVaArg), [@cVaCopy](https://ziglang.org/documentation/0.17.1/#cVaCopy), [@cVaStart](https://ziglang.org/documentation/0.17.1/#cVaStart)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cVaEnd)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cVaEnd", .compiler_param_count = 1 },
    .{ .name = "@cVaStart", .signature = "@cVaStart() std.lang.VaList", .parameters = &.{}, .documentation = "Implements the C macro `va_start`. Only valid inside a variadic function.\n\nSee also: [@cVaArg](https://ziglang.org/documentation/0.17.1/#cVaArg), [@cVaCopy](https://ziglang.org/documentation/0.17.1/#cVaCopy), [@cVaEnd](https://ziglang.org/documentation/0.17.1/#cVaEnd)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cVaStart)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cVaStart", .compiler_param_count = 0 },
    .{ .name = "@call", .signature = "@call(modifier: std.lang.CallModifier, function: anytype, args: anytype) anytype", .parameters = &.{
        "modifier: std.lang.CallModifier",
        "function: anytype",
        "args: anytype",
    }, .documentation = "Calls a function, in the same way that invoking an expression with parentheses does:\n\nOfficial example: [test\\_call\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#call)\n\n`@call` allows more flexibility than normal function call syntax does. The `CallModifier` enum is reproduced here:\n\nOfficial example: [lang.CallModifier struct.zig](https://ziglang.org/documentation/0.17.1/#call)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#call)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#call", .compiler_param_count = 3 },
    .{ .name = "@ceil", .signature = "@ceil(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Returns the smallest integral value not less than the given floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\nWhen the inferred result type is an [integer](https://ziglang.org/documentation/0.17.1/#Integers), the integer part is extracted from the ceiled result. If that value cannot fit in the destination type, it invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#ceil)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#ceil", .compiler_param_count = 1 },
    .{ .name = "@clz", .signature = "@clz(operand: anytype) anytype", .parameters = &.{
        "operand: anytype",
    }, .documentation = "`@TypeOf(operand)` must be an integer type or an integer vector type.\n\n`operand` may be an [integer](https://ziglang.org/documentation/0.17.1/#Integers) or [vector](https://ziglang.org/documentation/0.17.1/#Vectors).\n\nCounts the number of most-significant (leading in a big-endian sense) zeroes in an integer - \"count leading zeroes\".\n\nThe return type is an unsigned integer or vector of unsigned integers with the minimum number of bits that can represent the bit count of the integer type.\n\nIf `operand` is zero, `@clz` returns the bit width of integer type `T`.\n\nSee also: [@ctz](https://ziglang.org/documentation/0.17.1/#ctz), [@popCount](https://ziglang.org/documentation/0.17.1/#popCount)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#clz)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#clz", .compiler_param_count = 1 },
    .{ .name = "@cmpxchgStrong", .signature = "@cmpxchgStrong(comptime T: type, ptr: *T, expected_value: T, new_value: T, success_order: AtomicOrder, fail_order: AtomicOrder) ?T", .parameters = &.{
        "comptime T: type",
        "ptr: *T",
        "expected_value: T",
        "new_value: T",
        "success_order: AtomicOrder",
        "fail_order: AtomicOrder",
    }, .documentation = "This function performs a strong atomic compare-and-exchange operation, returning `null` if the current value is the given expected value. It's the equivalent of this code, except atomic:\n\nOfficial example: [not\\_atomic\\_cmpxchgStrong.zig](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong)\n\nIf you are using cmpxchg in a retry loop, [@cmpxchgWeak](https://ziglang.org/documentation/0.17.1/#cmpxchgWeak) is the better choice, because it can be implemented more efficiently in machine instructions.\n\n`T` must be a pointer, a `bool`, an integer, an enum, or a packed struct.\n\n`@typeInfo(@TypeOf(ptr)).pointer.alignment` must be `>= @sizeOf(T).`\n\n`AtomicOrder` can be found with `@import(\"std\").lang.AtomicOrder`.\n\nSee also: [@atomicStore](https://ziglang.org/documentation/0.17.1/#atomicStore), [@atomicLoad](https://ziglang.org/documentation/0.17.1/#atomicLoad), [@atomicRmw](https://ziglang.org/documentation/0.17.1/#atomicRmw), [@cmpxchgWeak](https://ziglang.org/documentation/0.17.1/#cmpxchgWeak)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cmpxchgStrong", .compiler_param_count = 6 },
    .{ .name = "@cmpxchgWeak", .signature = "@cmpxchgWeak(comptime T: type, ptr: *T, expected_value: T, new_value: T, success_order: AtomicOrder, fail_order: AtomicOrder) ?T", .parameters = &.{
        "comptime T: type",
        "ptr: *T",
        "expected_value: T",
        "new_value: T",
        "success_order: AtomicOrder",
        "fail_order: AtomicOrder",
    }, .documentation = "This function performs a weak atomic compare-and-exchange operation, returning `null` if the current value is the given expected value. It's the equivalent of this code, except atomic:\n\n```zig\nfn cmpxchgWeakButNotAtomic(comptime T: type, ptr: *T, expected_value: T, new_value: T) ?T {\n    const old_value = ptr.*;\n    if (old_value == expected_value and usuallyTrueButSometimesFalse()) {\n        ptr.* = new_value;\n        return null;\n    } else {\n        return old_value;\n    }\n}\n      \n```\n\nIf you are using cmpxchg in a retry loop, the sporadic failure will be no problem, and `cmpxchgWeak` is the better choice, because it can be implemented more efficiently in machine instructions. However if you need a stronger guarantee, use [@cmpxchgStrong](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong).\n\n`T` must be a pointer, a `bool`, an integer, an enum, or a packed struct.\n\n`@typeInfo(@TypeOf(ptr)).pointer.alignment` must be `>= @sizeOf(T).`\n\n`AtomicOrder` can be found with `@import(\"std\").lang.AtomicOrder`.\n\nSee also: [@atomicStore](https://ziglang.org/documentation/0.17.1/#atomicStore), [@atomicLoad](https://ziglang.org/documentation/0.17.1/#atomicLoad), [@atomicRmw](https://ziglang.org/documentation/0.17.1/#atomicRmw), [@cmpxchgStrong](https://ziglang.org/documentation/0.17.1/#cmpxchgStrong)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cmpxchgWeak)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cmpxchgWeak", .compiler_param_count = 6 },
    .{ .name = "@compileError", .signature = "@compileError(comptime msg: []const u8) noreturn", .parameters = &.{
        "comptime msg: []const u8",
    }, .documentation = "This function, when semantically analyzed, causes a compile error with the message `msg`.\n\nThere are several ways that code avoids being semantically checked, such as using `if` or `switch` with compile time constants, and `comptime` functions.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#compileError)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#compileError", .compiler_param_count = 1 },
    .{ .name = "@compileLog", .signature = "@compileLog(...) void", .parameters = &.{
        "...",
    }, .documentation = "This function prints the arguments passed to it at compile-time.\n\nTo prevent accidentally leaving compile log statements in a codebase, a compilation error is added to the build, pointing to the compile log statement. This error prevents code from being generated, but does not otherwise interfere with analysis.\n\nThis function can be used to do \"printf debugging\" on compile-time executing code.\n\nOfficial example: [test\\_compileLog\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#compileLog)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#compileLog)", .variadic = true, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#compileLog", .compiler_param_count = null },
    .{ .name = "@constCast", .signature = "@constCast(value: anytype) DestType", .parameters = &.{
        "value: anytype",
    }, .documentation = "Remove `const` qualifier from a pointer.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#constCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#constCast", .compiler_param_count = 1 },
    .{ .name = "@cos", .signature = "@cos(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Cosine trigonometric function on a floating point number in radians. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#cos)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#cos", .compiler_param_count = 1 },
    .{ .name = "@ctz", .signature = "@ctz(operand: anytype) anytype", .parameters = &.{
        "operand: anytype",
    }, .documentation = "`@TypeOf(operand)` must be an integer type or an integer vector type.\n\n`operand` may be an [integer](https://ziglang.org/documentation/0.17.1/#Integers) or [vector](https://ziglang.org/documentation/0.17.1/#Vectors).\n\nCounts the number of least-significant (trailing in a big-endian sense) zeroes in an integer - \"count trailing zeroes\".\n\nThe return type is an unsigned integer or vector of unsigned integers with the minimum number of bits that can represent the bit count of the integer type.\n\nIf `operand` is zero, `@ctz` returns the bit width of integer type `T`.\n\nSee also: [@clz](https://ziglang.org/documentation/0.17.1/#clz), [@popCount](https://ziglang.org/documentation/0.17.1/#popCount)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#ctz)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#ctz", .compiler_param_count = 1 },
    .{ .name = "@disableInstrumentation", .signature = null, .parameters = &.{}, .documentation = "`@disableInstrumentation` is present in the Zig 0.17.1 compiler builtin registry (parameter count: 0), but has no entry in that version's official Language Reference. No official signature or semantic documentation is available in the vendored source.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#Builtin-Functions) · [Official compiler source archive](https://ziglang.org/download/0.17.1/zig-0.17.1.tar.xz) (`lib/std/zig/BuiltinFn.zig`)", .variadic = false, .documented = false, .source_url = "https://ziglang.org/documentation/0.17.1/#Builtin-Functions", .compiler_param_count = 0 },
    .{ .name = "@disableIntrinsics", .signature = null, .parameters = &.{}, .documentation = "`@disableIntrinsics` is present in the Zig 0.17.1 compiler builtin registry (parameter count: 0), but has no entry in that version's official Language Reference. No official signature or semantic documentation is available in the vendored source.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#Builtin-Functions) · [Official compiler source archive](https://ziglang.org/download/0.17.1/zig-0.17.1.tar.xz) (`lib/std/zig/BuiltinFn.zig`)", .variadic = false, .documented = false, .source_url = "https://ziglang.org/documentation/0.17.1/#Builtin-Functions", .compiler_param_count = 0 },
    .{ .name = "@divCeil", .signature = "@divCeil(numerator: T, denominator: T) T", .parameters = &.{
        "numerator: T",
        "denominator: T",
    }, .documentation = "Ceiled division. Rounds toward positive infinity. Caller guarantees `denominator != 0` and `!(@typeInfo(T) == .int and T.is_signed and numerator == std.math.minInt(T) and denominator == -1)`.\n\n- `@divCeil(5, 3) == 2`\n- `@divCeil(-5, 3) == -1`\n\nFor a function that returns a possible error code, use `@import(\"std\").math.divCeil`.\n\nSee also: [@divFloor](https://ziglang.org/documentation/0.17.1/#divFloor), [@divTrunc](https://ziglang.org/documentation/0.17.1/#divTrunc), [@divExact](https://ziglang.org/documentation/0.17.1/#divExact)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#divCeil)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#divCeil", .compiler_param_count = 2 },
    .{ .name = "@divExact", .signature = "@divExact(numerator: T, denominator: T) T", .parameters = &.{
        "numerator: T",
        "denominator: T",
    }, .documentation = "Exact division. Caller guarantees `denominator != 0` and `@divTrunc(numerator, denominator) * denominator == numerator`.\n\n- `@divExact(6, 3) == 2`\n- `@divExact(a, b) * b == a`\n\nFor a function that returns a possible error code, use `@import(\"std\").math.divExact`.\n\nSee also: [@divTrunc](https://ziglang.org/documentation/0.17.1/#divTrunc), [@divFloor](https://ziglang.org/documentation/0.17.1/#divFloor), [@divCeil](https://ziglang.org/documentation/0.17.1/#divCeil)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#divExact)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#divExact", .compiler_param_count = 2 },
    .{ .name = "@divFloor", .signature = "@divFloor(numerator: T, denominator: T) T", .parameters = &.{
        "numerator: T",
        "denominator: T",
    }, .documentation = "Floored division. Rounds toward negative infinity. For unsigned integers it is the same as `numerator / denominator`. Caller guarantees `denominator != 0` and `!(@typeInfo(T) == .int and T.is_signed and numerator == std.math.minInt(T) and denominator == -1)`.\n\n- `@divFloor(-5, 3) == -2`\n- `(@divFloor(a, b) * b) + @mod(a, b) == a`\n\nFor a function that returns a possible error code, use `@import(\"std\").math.divFloor`.\n\nSee also: [@divTrunc](https://ziglang.org/documentation/0.17.1/#divTrunc), [@divCeil](https://ziglang.org/documentation/0.17.1/#divCeil), [@divExact](https://ziglang.org/documentation/0.17.1/#divExact)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#divFloor)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#divFloor", .compiler_param_count = 2 },
    .{ .name = "@divTrunc", .signature = "@divTrunc(numerator: T, denominator: T) T", .parameters = &.{
        "numerator: T",
        "denominator: T",
    }, .documentation = "Truncated division. Rounds toward zero. For unsigned integers it is the same as `numerator / denominator`. Caller guarantees `denominator != 0` and `!(@typeInfo(T) == .int and T.is_signed and numerator == std.math.minInt(T) and denominator == -1)`.\n\n- `@divTrunc(-5, 3) == -1`\n- `(@divTrunc(a, b) * b) + @rem(a, b) == a`\n\nFor a function that returns a possible error code, use `@import(\"std\").math.divTrunc`.\n\nSee also: [@divFloor](https://ziglang.org/documentation/0.17.1/#divFloor), [@divCeil](https://ziglang.org/documentation/0.17.1/#divCeil), [@divExact](https://ziglang.org/documentation/0.17.1/#divExact)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#divTrunc)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#divTrunc", .compiler_param_count = 2 },
    .{ .name = "@embedFile", .signature = "@embedFile(comptime path: []const u8) *const [N:0]u8", .parameters = &.{
        "comptime path: []const u8",
    }, .documentation = "This function returns a compile time constant pointer to null-terminated, fixed-size array with length equal to the byte count of the file given by `path`. The contents of the array are the contents of the file. This is equivalent to a [string literal](https://ziglang.org/documentation/0.17.1/#String-Literals-and-Unicode-Code-Point-Literals) with the file contents.\n\n`path` is absolute or relative to the current file, just like `@import`.\n\nSee also: [@import](https://ziglang.org/documentation/0.17.1/#import)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#embedFile)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#embedFile", .compiler_param_count = 1 },
    .{ .name = "@enumFromInt", .signature = "@enumFromInt(integer: anytype) anytype", .parameters = &.{
        "integer: anytype",
    }, .documentation = "Deprecated. Use [@fromBackingInt](https://ziglang.org/documentation/0.17.1/#fromBackingInt) or [@bitCast](https://ziglang.org/documentation/0.17.1/#bitCast) instead.\n\nConverts an integer into an [enum](https://ziglang.org/documentation/0.17.1/#enum) value. The return type is the inferred result type.\n\nAttempting to convert an integer with no corresponding value in the enum invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior). Note that a [non-exhaustive enum](https://ziglang.org/documentation/0.17.1/#Non-exhaustive-enum) has corresponding values for all integers in the enum's integer tag type: the `_` value represents all the remaining unnamed integers in the enum's tag type.\n\nSee also: [@intFromEnum](https://ziglang.org/documentation/0.17.1/#intFromEnum)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#enumFromInt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#enumFromInt", .compiler_param_count = 1 },
    .{ .name = "@errorCast", .signature = "@errorCast(value: anytype) anytype", .parameters = &.{
        "value: anytype",
    }, .documentation = "Converts an error set or error union value from one error set to another error set. The return type is the inferred result type. Attempting to convert an error which is not in the destination error set results in safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#errorCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#errorCast", .compiler_param_count = 1 },
    .{ .name = "@errorFromInt", .signature = "@errorFromInt(value: @Int(.unsigned, @bitSizeOf(anyerror))) anyerror", .parameters = &.{
        "value: @Int(.unsigned, @bitSizeOf(anyerror))",
    }, .documentation = "Converts from the integer representation of an error into [The Global Error Set](https://ziglang.org/documentation/0.17.1/#The-Global-Error-Set) type.\n\nIt is generally recommended to avoid this cast, as the integer representation of an error is not stable across source code changes.\n\nAttempting to convert an integer that does not correspond to any error results in safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\nSee also: [@intFromError](https://ziglang.org/documentation/0.17.1/#intFromError)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#errorFromInt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#errorFromInt", .compiler_param_count = 1 },
    .{ .name = "@errorName", .signature = "@errorName(err: anyerror) [:0]const u8", .parameters = &.{
        "err: anyerror",
    }, .documentation = "This function returns the string representation of an error. The string representation of `error.OutOfMem` is `\"OutOfMem\"`.\n\nIf there are no calls to `@errorName` in an entire application, or all calls have a compile-time known value for `err`, then no error name table will be generated.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#errorName)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#errorName", .compiler_param_count = 1 },
    .{ .name = "@errorReturnTrace", .signature = "@errorReturnTrace() ?*std.lang.StackTrace", .parameters = &.{}, .documentation = "If the binary is built with error return tracing, and this function is invoked in a function that calls a function with an error or error union return type, returns a stack trace object. Otherwise returns [null](https://ziglang.org/documentation/0.17.1/#null).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#errorReturnTrace)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#errorReturnTrace", .compiler_param_count = 0 },
    .{ .name = "@exp", .signature = "@exp(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Base-e exponential function on a floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#exp)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#exp", .compiler_param_count = 1 },
    .{ .name = "@exp2", .signature = "@exp2(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Base-2 exponential function on a floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#exp2)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#exp2", .compiler_param_count = 1 },
    .{ .name = "@export", .signature = "@export(comptime ptr: *const anyopaque, comptime options: std.lang.ExportOptions) void", .parameters = &.{
        "comptime ptr: *const anyopaque",
        "comptime options: std.lang.ExportOptions",
    }, .documentation = "Creates a symbol in the output object file which refers to the target of `ptr`.\n\n`ptr` must point to a global variable or a comptime-known constant.\n\nThis builtin can be called from a [comptime](https://ziglang.org/documentation/0.17.1/#comptime) block to conditionally export symbols. When `ptr` points to a function with the C calling convention and `options.linkage` is `.strong`, this is equivalent to the `export` keyword used on a function:\n\nOfficial example: [export\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#export)\n\nThis is equivalent to:\n\nOfficial example: [export\\_builtin\\_equivalent\\_code.zig](https://ziglang.org/documentation/0.17.1/#export)\n\nNote that even when using `export`, the `@\"foo\"` syntax for [identifiers](https://ziglang.org/documentation/0.17.1/#Identifiers) can be used to choose any string for the symbol name:\n\nOfficial example: [export\\_any\\_symbol\\_name.zig](https://ziglang.org/documentation/0.17.1/#export)\n\nWhen looking at the resulting object, you can see the symbol is used verbatim:\n\n```\n00000000000001f0 T A function name that is a complete sentence.\n```\n\nSee also: [Exporting a C Library](https://ziglang.org/documentation/0.17.1/#Exporting-a-C-Library)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#export)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#export", .compiler_param_count = 2 },
    .{ .name = "@extern", .signature = "@extern(T: type, comptime options: std.lang.ExternOptions) T", .parameters = &.{
        "T: type",
        "comptime options: std.lang.ExternOptions",
    }, .documentation = "Creates a reference to an external symbol in the output object file. T must be a pointer type.\n\nSee also: [@export](https://ziglang.org/documentation/0.17.1/#export)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#extern)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#extern", .compiler_param_count = 2 },
    .{ .name = "@field", .signature = "@field(lhs: anytype, comptime field_name: []const u8) (field)", .parameters = &.{
        "lhs: anytype",
        "comptime field_name: []const u8",
    }, .documentation = "Performs field access by a compile-time string. Works on both fields and declarations.\n\nOfficial example: [test\\_field\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#field)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#field)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#field", .compiler_param_count = 2 },
    .{ .name = "@fieldParentPtr", .signature = "@fieldParentPtr(comptime field_name: []const u8, field_ptr: *T) anytype", .parameters = &.{
        "comptime field_name: []const u8",
        "field_ptr: *T",
    }, .documentation = "Given a pointer to a struct or union field, returns a pointer to the struct or union containing that field. The return type (pointer to the parent struct or union in question) is the inferred result type.\n\nIf `field_ptr` does not point to the `field_name` field of an instance of the result type, and the result type has ill-defined layout, invokes unchecked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#fieldParentPtr)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#fieldParentPtr", .compiler_param_count = 2 },
    .{ .name = "@floatCast", .signature = "@floatCast(value: anytype) anytype", .parameters = &.{
        "value: anytype",
    }, .documentation = "Convert from one float type to another. This cast is safe, but may cause the numeric value to lose precision. The return type is the inferred result type.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#floatCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#floatCast", .compiler_param_count = 1 },
    .{ .name = "@floatFromInt", .signature = "@floatFromInt(int: anytype) anytype", .parameters = &.{
        "int: anytype",
    }, .documentation = "Converts an integer to the closest floating point representation. The return type is the inferred result type. To convert the other way, use [@round](https://ziglang.org/documentation/0.17.1/#round), [@floor](https://ziglang.org/documentation/0.17.1/#floor), [@ceil](https://ziglang.org/documentation/0.17.1/#ceil), or [@trunc](https://ziglang.org/documentation/0.17.1/#trunc). This operation is legal for all values of all integer types.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#floatFromInt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#floatFromInt", .compiler_param_count = 1 },
    .{ .name = "@floor", .signature = "@floor(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Returns the largest integral value not greater than the given floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\nWhen the inferred result type is an [integer](https://ziglang.org/documentation/0.17.1/#Integers), the integer part is extracted from the floored result. If that value cannot fit in the destination type, it invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#floor)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#floor", .compiler_param_count = 1 },
    .{ .name = "@frame", .signature = null, .parameters = &.{}, .documentation = "`@frame` is present in the Zig 0.17.1 compiler builtin registry (parameter count: 0), but has no entry in that version's official Language Reference. No official signature or semantic documentation is available in the vendored source.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#Builtin-Functions) · [Official compiler source archive](https://ziglang.org/download/0.17.1/zig-0.17.1.tar.xz) (`lib/std/zig/BuiltinFn.zig`)", .variadic = false, .documented = false, .source_url = "https://ziglang.org/documentation/0.17.1/#Builtin-Functions", .compiler_param_count = 0 },
    .{ .name = "@frameAddress", .signature = "@frameAddress() usize", .parameters = &.{}, .documentation = "This function returns the base pointer of the current stack frame.\n\nThe implications of this are target-specific and not consistent across all platforms. The frame address may not be available in release mode due to aggressive optimizations.\n\nThis function is only valid within function scope.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#frameAddress)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#frameAddress", .compiler_param_count = 0 },
    .{ .name = "@fromBackingInt", .signature = "@fromBackingInt(backing_int: BackingInt(T)) T", .parameters = &.{
        "backing_int: BackingInt(T)",
    }, .documentation = "Converts an integer into a [enum](https://ziglang.org/documentation/0.17.1/#enum), a [packed struct](https://ziglang.org/documentation/0.17.1/#packed-struct) or a [packed union](https://ziglang.org/documentation/0.17.1/#packed-union) value. The return type is the inferred result type.\n\nAttempting to convert an integer with no corresponding tag value to an `enum` invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior). Note that a [non-exhaustive enum](https://ziglang.org/documentation/0.17.1/#Non-exhaustive-enum) has corresponding values for all integers in the enum's integer tag type: the `_` value represents all the remaining unnamed integers in the enum's tag type.\n\nSee also: [@backingInt](https://ziglang.org/documentation/0.17.1/#backingInt), [@bitCast](https://ziglang.org/documentation/0.17.1/#bitCast)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#fromBackingInt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#fromBackingInt", .compiler_param_count = 1 },
    .{ .name = "@hasDecl", .signature = "@hasDecl(comptime Namespace: type, comptime name: []const u8) bool", .parameters = &.{
        "comptime Namespace: type",
        "comptime name: []const u8",
    }, .documentation = "Returns whether or not a [Namespace](https://ziglang.org/documentation/0.17.1/#Namespace) has a public declaration matching `name`.\n\nOfficial example: [test\\_hasDecl\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#hasDecl)\n\nCaution: using `@hasDecl` to implement conditional compilation based on the presence or absence of declarations in an API runs the risk of introducing dead code into the codebase, unnoticed. For example, if the field is ever renamed, code which uses `@hasDecl` will compile successfully while failing to enable or disable an intended block of code. Even a simple typo in the field name passed to `@hasDecl` would go unnoticed by the compiler. Thus, it is safer to use alternative methods to check for the presence or absence of a particular declaration where possible. For example, if the target operating system would indicate whether a particular function is available, it is more maintainable to check `@import(\"builtin\").target.os.tag` rather than `@hasDecl`.\n\nSee also: [@hasField](https://ziglang.org/documentation/0.17.1/#hasField)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#hasDecl)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#hasDecl", .compiler_param_count = 2 },
    .{ .name = "@hasField", .signature = "@hasField(comptime T: type, comptime name: []const u8) bool", .parameters = &.{
        "comptime T: type",
        "comptime name: []const u8",
    }, .documentation = "Returns whether the field name of a struct, union, or enum exists.\n\nThe result is a compile time constant.\n\nIt does not include functions, variables, or constants.\n\nSee also: [@hasDecl](https://ziglang.org/documentation/0.17.1/#hasDecl)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#hasField)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#hasField", .compiler_param_count = 2 },
    .{ .name = "@import", .signature = "@import(comptime target: []const u8) anytype", .parameters = &.{
        "comptime target: []const u8",
    }, .documentation = "Imports the file at `target`, adding it to the compilation if it is not already added. `target` is either a relative path to another file from the file containing the `@import` call, or it is the name of a [module](https://ziglang.org/documentation/0.17.1/#Compilation-Model), with the import referring to the root source file of that module. Either way, the file path must end in either `.zig` (for a Zig source file) or `.zon` (for a ZON data file).\n\nIf `target` refers to a Zig source file, then `@import` returns that file's [corresponding struct type](https://ziglang.org/documentation/0.17.1/#Source-File-Structs), essentially as if the builtin call was replaced by `struct { FILE_CONTENTS }`. The return type is `type`.\n\nIf `target` refers to a ZON file, then `@import` returns the value of the literal in the file. If there is an inferred [result type](https://ziglang.org/documentation/0.17.1/#Result-Types), then the return type is that type, and the ZON literal is interpreted as that type ([Result Types](https://ziglang.org/documentation/0.17.1/#Result-Types) are propagated through the ZON expression). Otherwise, the return type is the type of the equivalent Zig expression, essentially as if the builtin call was replaced by the ZON file contents.\n\nThe following modules are always available for import:\n\n- `@import(\"std\")` - Zig Standard Library\n- `@import(\"builtin\")` - Target-specific information. The command `zig build-exe --show-builtin` outputs the source to stdout for reference.\n- `@import(\"root\")` - Alias for the root module. In typical project structures, this means it refers back to `src/main.zig`.\n\nSee also: [Compile Variables](https://ziglang.org/documentation/0.17.1/#Compile-Variables), [@embedFile](https://ziglang.org/documentation/0.17.1/#embedFile)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#import)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#import", .compiler_param_count = 1 },
    .{ .name = "@inComptime", .signature = "@inComptime() bool", .parameters = &.{}, .documentation = "Returns whether the builtin was run in a `comptime` context. The result is a compile-time constant.\n\nThis can be used to provide alternative, comptime-friendly implementations of functions. It should not be used, for instance, to exclude certain functions from being evaluated at comptime.\n\nSee also: [comptime](https://ziglang.org/documentation/0.17.1/#comptime)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#inComptime)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#inComptime", .compiler_param_count = 0 },
    .{ .name = "@intCast", .signature = "@intCast(int: anytype) anytype", .parameters = &.{
        "int: anytype",
    }, .documentation = "Converts an integer to another integer while keeping the same numerical value. The return type is the inferred result type. Attempting to convert a number which is out of range of the destination type results in safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\nOfficial example: [test\\_intCast\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#intCast)\n\nTo truncate the significant bits of a number out of range of the destination type, use [@truncate](https://ziglang.org/documentation/0.17.1/#truncate).\n\nIf `T` is `comptime_int`, then this is semantically equivalent to [Type Coercion](https://ziglang.org/documentation/0.17.1/#Type-Coercion).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#intCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#intCast", .compiler_param_count = 1 },
    .{ .name = "@intFromBool", .signature = "@intFromBool(value: bool) u1", .parameters = &.{
        "value: bool",
    }, .documentation = "Converts `true` to `@as(u1, 1)` and `false` to `@as(u1, 0)`.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#intFromBool)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#intFromBool", .compiler_param_count = 1 },
    .{ .name = "@intFromEnum", .signature = "@intFromEnum(enum_or_tagged_union: anytype) anytype", .parameters = &.{
        "enum_or_tagged_union: anytype",
    }, .documentation = "Deprecated. Use [@backingInt](https://ziglang.org/documentation/0.17.1/#backingInt) or [@bitCast](https://ziglang.org/documentation/0.17.1/#bitCast) instead.\n\nConverts an enumeration value into its integer tag type. When a tagged union is passed, the tag value is used as the enumeration value.\n\nSee also: [@enumFromInt](https://ziglang.org/documentation/0.17.1/#enumFromInt)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#intFromEnum)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#intFromEnum", .compiler_param_count = 1 },
    .{ .name = "@intFromError", .signature = "@intFromError(err: anytype) @Int(.unsigned, @bitSizeOf(anyerror))", .parameters = &.{
        "err: anytype",
    }, .documentation = "Supports the following types:\n\n- [The Global Error Set](https://ziglang.org/documentation/0.17.1/#The-Global-Error-Set)\n- [Error Set Type](https://ziglang.org/documentation/0.17.1/#Error-Set-Type)\n- [Error Union Type](https://ziglang.org/documentation/0.17.1/#Error-Union-Type)\n\nConverts an error to the integer representation of an error.\n\nIt is generally recommended to avoid this cast, as the integer representation of an error is not stable across source code changes.\n\nSee also: [@errorFromInt](https://ziglang.org/documentation/0.17.1/#errorFromInt)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#intFromError)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#intFromError", .compiler_param_count = 1 },
    .{ .name = "@intFromFloat", .signature = "@intFromFloat(float: anytype) anytype", .parameters = &.{
        "float: anytype",
    }, .documentation = "Deprecated. Equivalent to [@trunc](https://ziglang.org/documentation/0.17.1/#trunc).\n\nSee also: [@floatFromInt](https://ziglang.org/documentation/0.17.1/#floatFromInt), [@round](https://ziglang.org/documentation/0.17.1/#round), [@floor](https://ziglang.org/documentation/0.17.1/#floor), [@ceil](https://ziglang.org/documentation/0.17.1/#ceil), [@trunc](https://ziglang.org/documentation/0.17.1/#trunc)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#intFromFloat)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#intFromFloat", .compiler_param_count = 1 },
    .{ .name = "@intFromPtr", .signature = "@intFromPtr(value: anytype) usize", .parameters = &.{
        "value: anytype",
    }, .documentation = "Converts `value` to a `usize` which is the address of the pointer. `value` can be `*T` or `?*T`.\n\nSee also: [@ptrFromInt](https://ziglang.org/documentation/0.17.1/#ptrFromInt)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#intFromPtr)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#intFromPtr", .compiler_param_count = 1 },
    .{ .name = "@log", .signature = "@log(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Returns the natural logarithm of a floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#log)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#log", .compiler_param_count = 1 },
    .{ .name = "@log10", .signature = "@log10(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Returns the logarithm to the base 10 of a floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#log10)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#log10", .compiler_param_count = 1 },
    .{ .name = "@log2", .signature = "@log2(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Returns the logarithm to the base 2 of a floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#log2)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#log2", .compiler_param_count = 1 },
    .{ .name = "@max", .signature = "@max(...) T", .parameters = &.{
        "...",
    }, .documentation = "Takes two or more arguments and returns the biggest value included (the maximum). This builtin accepts integers, floats, and vectors of either. In the latter case, the operation is performed element wise.\n\nNaNs are handled as follows: return the biggest non-NaN value included. If all operands are NaN, return NaN.\n\nSee also: [@min](https://ziglang.org/documentation/0.17.1/#min), [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#max)", .variadic = true, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#max", .compiler_param_count = null },
    .{ .name = "@memcpy", .signature = "@memcpy(noalias dest, noalias source) void", .parameters = &.{
        "noalias dest",
        "noalias source",
    }, .documentation = "This function copies bytes from one region of memory to another.\n\n`dest` must be a mutable slice, a mutable pointer to an array, or a mutable many-item [pointer](https://ziglang.org/documentation/0.17.1/#Pointers). It may have any alignment, and it may have any element type.\n\n`source` must be a slice, a pointer to an array, or a many-item [pointer](https://ziglang.org/documentation/0.17.1/#Pointers). It may have any alignment, and it may have any element type.\n\nThe `source` element type must have the same in-memory representation as the `dest` element type.\n\nSimilar to [for](https://ziglang.org/documentation/0.17.1/#for) loops, at least one of `source` and `dest` must provide a length, and if two lengths are provided, they must be equal.\n\nFinally, the two memory regions must not overlap.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#memcpy)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#memcpy", .compiler_param_count = 2 },
    .{ .name = "@memmove", .signature = "@memmove(dest, source) void", .parameters = &.{
        "dest",
        "source",
    }, .documentation = "This function copies bytes from one region of memory to another, but unlike [@memcpy](https://ziglang.org/documentation/0.17.1/#memcpy) the regions may overlap.\n\n`dest` must be a mutable slice, a mutable pointer to an array, or a mutable many-item [pointer](https://ziglang.org/documentation/0.17.1/#Pointers). It may have any alignment, and it may have any element type.\n\n`source` must be a slice, a pointer to an array, or a many-item [pointer](https://ziglang.org/documentation/0.17.1/#Pointers). It may have any alignment, and it may have any element type.\n\nThe `source` element type must have the same in-memory representation as the `dest` element type.\n\nSimilar to [for](https://ziglang.org/documentation/0.17.1/#for) loops, at least one of `source` and `dest` must provide a length, and if two lengths are provided, they must be equal.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#memmove)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#memmove", .compiler_param_count = 2 },
    .{ .name = "@memset", .signature = "@memset(dest, elem) void", .parameters = &.{
        "dest",
        "elem",
    }, .documentation = "This function sets all the elements of a memory region to `elem`.\n\n`dest` must be a mutable slice or a mutable pointer to an array. It may have any alignment, and it may have any element type.\n\n`elem` is coerced to the element type of `dest`.\n\nFor securely zeroing out sensitive contents from memory, you should use `std.crypto.secureZero`\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#memset)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#memset", .compiler_param_count = 2 },
    .{ .name = "@min", .signature = "@min(...) T", .parameters = &.{
        "...",
    }, .documentation = "Takes two or more arguments and returns the smallest value included (the minimum). This builtin accepts integers, floats, and vectors of either. In the latter case, the operation is performed element wise.\n\nNaNs are handled as follows: return the smallest non-NaN value included. If all operands are NaN, return NaN.\n\nSee also: [@max](https://ziglang.org/documentation/0.17.1/#max), [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#min)", .variadic = true, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#min", .compiler_param_count = null },
    .{ .name = "@mod", .signature = "@mod(numerator: T, denominator: T) T", .parameters = &.{
        "numerator: T",
        "denominator: T",
    }, .documentation = "Modulus division. For unsigned integers this is the same as `numerator % denominator`. Caller guarantees `denominator != 0`, otherwise the operation will result in a [Remainder Division by Zero](https://ziglang.org/documentation/0.17.1/#Remainder-Division-by-Zero) when runtime safety checks are enabled.\n\n- `@mod(-5, 3) == 1`\n- `(@divFloor(a, b) * b) + @mod(a, b) == a`\n\nFor a function that returns an error code, see `@import(\"std\").math.mod`.\n\nSee also: [@rem](https://ziglang.org/documentation/0.17.1/#rem)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#mod)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#mod", .compiler_param_count = 2 },
    .{ .name = "@mulAdd", .signature = "@mulAdd(comptime T: type, a: T, b: T, c: T) T", .parameters = &.{
        "comptime T: type",
        "a: T",
        "b: T",
        "c: T",
    }, .documentation = "Fused multiply-add, similar to `(a * b) + c`, except only rounds once, and is thus more accurate.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#mulAdd)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#mulAdd", .compiler_param_count = 4 },
    .{ .name = "@mulWithOverflow", .signature = "@mulWithOverflow(a: anytype, b: anytype) struct { @TypeOf(a, b), u1 }", .parameters = &.{
        "a: anytype",
        "b: anytype",
    }, .documentation = "Performs `a * b` and returns a tuple with the result and a possible overflow bit.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#mulWithOverflow)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#mulWithOverflow", .compiler_param_count = 2 },
    .{ .name = "@offsetOf", .signature = "@offsetOf(comptime T: type, comptime field_name: []const u8) comptime_int", .parameters = &.{
        "comptime T: type",
        "comptime field_name: []const u8",
    }, .documentation = "Returns the byte offset of a field relative to its containing struct.\n\nSee also: [@bitOffsetOf](https://ziglang.org/documentation/0.17.1/#bitOffsetOf)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#offsetOf)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#offsetOf", .compiler_param_count = 2 },
    .{ .name = "@panic", .signature = "@panic(message: []const u8) noreturn", .parameters = &.{
        "message: []const u8",
    }, .documentation = "Invokes the panic handler function. By default the panic handler function calls the public `panic` function exposed in the root source file, or if there is not one specified, the `std.lang.default_panic` function from `std/lang.zig`.\n\nGenerally it is better to use `@import(\"std\").debug.panic`. However, `@panic` can be useful for 2 scenarios:\n\n- From library code, calling the programmer's panic function if they exposed one in the root source file.\n- When mixing C and Zig code, calling the canonical panic implementation across multiple .o files.\n\nSee also: [Panic Handler](https://ziglang.org/documentation/0.17.1/#Panic-Handler)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#panic)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#panic", .compiler_param_count = 1 },
    .{ .name = "@popCount", .signature = "@popCount(operand: anytype) anytype", .parameters = &.{
        "operand: anytype",
    }, .documentation = "`@TypeOf(operand)` must be an integer type.\n\n`operand` may be an [integer](https://ziglang.org/documentation/0.17.1/#Integers) or [vector](https://ziglang.org/documentation/0.17.1/#Vectors).\n\nCounts the number of bits set in an integer - \"population count\".\n\nThe return type is an unsigned integer or vector of unsigned integers with the minimum number of bits that can represent the bit count of the integer type.\n\nSee also: [@ctz](https://ziglang.org/documentation/0.17.1/#ctz), [@clz](https://ziglang.org/documentation/0.17.1/#clz)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#popCount)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#popCount", .compiler_param_count = 1 },
    .{ .name = "@prefetch", .signature = "@prefetch(ptr: anytype, comptime options: PrefetchOptions) void", .parameters = &.{
        "ptr: anytype",
        "comptime options: PrefetchOptions",
    }, .documentation = "This builtin tells the compiler to emit a prefetch instruction if supported by the target CPU. If the target CPU does not support the requested prefetch instruction, this builtin is a no-op. This function has no effect on the behavior of the program, only on the performance characteristics.\n\nThe `ptr` argument may be any pointer type and determines the memory address to prefetch. This function does not dereference the pointer, it is perfectly legal to pass a pointer to invalid memory to this function and no Illegal Behavior will result.\n\n`PrefetchOptions` can be found with `@import(\"std\").lang.PrefetchOptions`.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#prefetch)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#prefetch", .compiler_param_count = 2 },
    .{ .name = "@ptrCast", .signature = "@ptrCast(value: anytype) anytype", .parameters = &.{
        "value: anytype",
    }, .documentation = "Converts a pointer of one type to a pointer of another type. The return type is the inferred result type.\n\n[Optional Pointers](https://ziglang.org/documentation/0.17.1/#Optional-Pointers) are allowed. Casting an optional pointer which is [null](https://ziglang.org/documentation/0.17.1/#null) to a non-optional pointer invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n`@ptrCast` cannot be used for:\n\n- Removing `const` qualifier, use [@constCast](https://ziglang.org/documentation/0.17.1/#constCast).\n- Removing `volatile` qualifier, use [@volatileCast](https://ziglang.org/documentation/0.17.1/#volatileCast).\n- Changing pointer address space, use [@addrSpaceCast](https://ziglang.org/documentation/0.17.1/#addrSpaceCast).\n- Increasing pointer alignment, use [@alignCast](https://ziglang.org/documentation/0.17.1/#alignCast).\n- Casting a non-slice pointer to a slice, use slicing syntax `ptr[start..end]`.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#ptrCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#ptrCast", .compiler_param_count = 1 },
    .{ .name = "@ptrFromInt", .signature = "@ptrFromInt(address: usize) anytype", .parameters = &.{
        "address: usize",
    }, .documentation = "Converts an integer to a [pointer](https://ziglang.org/documentation/0.17.1/#Pointers). The return type is the inferred result type. To convert the other way, use [@intFromPtr](https://ziglang.org/documentation/0.17.1/#intFromPtr). Casting an address of 0 to a destination type which in not [optional](https://ziglang.org/documentation/0.17.1/#Optional-Pointers) and does not have the `allowzero` attribute will result in a [Pointer Cast Invalid Null](https://ziglang.org/documentation/0.17.1/#Pointer-Cast-Invalid-Null) panic when runtime safety checks are enabled.\n\nIf the destination pointer type does not allow address zero and `address` is zero, this invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\nSee also: [@intFromPtr](https://ziglang.org/documentation/0.17.1/#intFromPtr)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#ptrFromInt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#ptrFromInt", .compiler_param_count = 1 },
    .{ .name = "@reduce", .signature = "@reduce(comptime op: std.lang.ReduceOp, value: anytype) E", .parameters = &.{
        "comptime op: std.lang.ReduceOp",
        "value: anytype",
    }, .documentation = "Transforms a [vector](https://ziglang.org/documentation/0.17.1/#Vectors) into a scalar value (of type `E`) by performing a sequential horizontal reduction of its elements using the specified operator `op`.\n\nNot every operator is available for every vector element type:\n\n- Every operator is available for [integer](https://ziglang.org/documentation/0.17.1/#Integers) vectors.\n- `.And`, `.Or`, `.Xor` are additionally available for `bool` vectors,\n- `.Min`, `.Max`, `.Add`, `.Mul` are additionally available for [floating point](https://ziglang.org/documentation/0.17.1/#Floats) vectors,\n\nNote that `.Add` and `.Mul` reductions on integral types are wrapping; when applied on floating point types the operation associativity is preserved, unless the float mode is set to `.optimized`.\n\nOfficial example: [test\\_reduce\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#reduce)\n\nSee also: [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors), [@setFloatMode](https://ziglang.org/documentation/0.17.1/#setFloatMode)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#reduce)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#reduce", .compiler_param_count = 2 },
    .{ .name = "@rem", .signature = "@rem(numerator: T, denominator: T) T", .parameters = &.{
        "numerator: T",
        "denominator: T",
    }, .documentation = "Remainder division. For unsigned integers this is the same as `numerator % denominator`. Caller guarantees `denominator != 0`, otherwise the operation will result in a [Remainder Division by Zero](https://ziglang.org/documentation/0.17.1/#Remainder-Division-by-Zero) when runtime safety checks are enabled.\n\n- `@rem(-5, 3) == -2`\n- `(@divTrunc(a, b) * b) + @rem(a, b) == a`\n\nFor a function that returns an error code, see `@import(\"std\").math.rem`.\n\nSee also: [@mod](https://ziglang.org/documentation/0.17.1/#mod)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#rem)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#rem", .compiler_param_count = 2 },
    .{ .name = "@returnAddress", .signature = "@returnAddress() usize", .parameters = &.{}, .documentation = "This function returns the address of the next machine code instruction that will be executed when the current function returns.\n\nThe implications of this are target-specific and not consistent across all platforms.\n\nThis function is only valid within function scope. If the function gets inlined into a calling function, the returned address will apply to the calling function.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#returnAddress)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#returnAddress", .compiler_param_count = 0 },
    .{ .name = "@round", .signature = "@round(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Rounds the given floating point number to the nearest integer. If two integers are equally close, rounds away from zero. Uses a dedicated hardware instruction when available.\n\nOfficial example: [test\\_round\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#round)\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\nWhen the inferred result type is an [integer](https://ziglang.org/documentation/0.17.1/#Integers), the integer part is extracted from the rounded result. If that value cannot fit in the destination type, it invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#round)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#round", .compiler_param_count = 1 },
    .{ .name = "@select", .signature = "@select(comptime T: type, pred: @Vector(len, bool), a: @Vector(len, T), b: @Vector(len, T)) @Vector(len, T)", .parameters = &.{
        "comptime T: type",
        "pred: @Vector(len, bool)",
        "a: @Vector(len, T)",
        "b: @Vector(len, T)",
    }, .documentation = "Selects values element-wise from `a` or `b` based on `pred`. If `pred[i]` is `true`, the corresponding element in the result will be `a[i]` and otherwise `b[i]`.\n\nSee also: [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#select)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#select", .compiler_param_count = 4 },
    .{ .name = "@setEvalBranchQuota", .signature = "@setEvalBranchQuota(comptime new_quota: u32) void", .parameters = &.{
        "comptime new_quota: u32",
    }, .documentation = "Increase the maximum number of backwards branches that compile-time code execution can use before giving up and making a compile error.\n\nIf the `new_quota` is smaller than the default quota (`1000`) or a previously explicitly set quota, it is ignored.\n\nExample:\n\nOfficial example: [test\\_without\\_setEvalBranchQuota\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#setEvalBranchQuota)\n\nNow we use `@setEvalBranchQuota`:\n\nOfficial example: [test\\_setEvalBranchQuota\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#setEvalBranchQuota)\n\nSee also: [comptime](https://ziglang.org/documentation/0.17.1/#comptime)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#setEvalBranchQuota)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#setEvalBranchQuota", .compiler_param_count = 1 },
    .{ .name = "@setFloatMode", .signature = "@setFloatMode(comptime mode: FloatMode) void", .parameters = &.{
        "comptime mode: FloatMode",
    }, .documentation = "Changes the current scope's rules about how floating point operations are defined.\n\n- `.strict` (default) - Floating point operations follow strict IEEE compliance.\n- `.optimized` - Floating point operations may do all of the following:\n  - Assume the arguments and result are not NaN. Optimizations are required to retain legal behavior over NaNs, but the value of the result is undefined.\n  - Assume the arguments and result are not +/-Inf. Optimizations are required to retain legal behavior over +/-Inf, but the value of the result is undefined.\n  - Treat the sign of a zero argument or result as insignificant.\n  - Use the reciprocal of an argument rather than perform division.\n  - Perform floating-point contraction (e.g. fusing a multiply followed by an addition into a fused multiply-add).\n  - Perform algebraically equivalent transformations that may change results in floating point (e.g. reassociate).\nThis is equivalent to `-ffast-math` in GCC.\n\nThe floating point mode is inherited by child scopes, and can be overridden in any scope. You can set the floating point mode in a struct or module scope by using a comptime block.\n\n`FloatMode` can be found with `@import(\"std\").lang.FloatMode`.\n\nSee also: [Floating Point Operations](https://ziglang.org/documentation/0.17.1/#Floating-Point-Operations)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#setFloatMode)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#setFloatMode", .compiler_param_count = 1 },
    .{ .name = "@setRuntimeSafety", .signature = "@setRuntimeSafety(comptime safety_on: bool) void", .parameters = &.{
        "comptime safety_on: bool",
    }, .documentation = "Sets whether runtime safety checks are enabled for the scope that contains the function call.\n\nOfficial example: [test\\_setRuntimeSafety\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#setRuntimeSafety)\n\nNote: it is [planned](https://github.com/ziglang/zig/issues/978) to replace `@setRuntimeSafety` with `@optimizeFor`\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#setRuntimeSafety)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#setRuntimeSafety", .compiler_param_count = 1 },
    .{ .name = "@shlExact", .signature = "@shlExact(value: T, shift_amt: Log2T) T", .parameters = &.{
        "value: T",
        "shift_amt: Log2T",
    }, .documentation = "Performs the left shift operation (`<<`). For unsigned integers, the result is [undefined](https://ziglang.org/documentation/0.17.1/#undefined) if any 1 bits are shifted out. For signed integers, the result is [undefined](https://ziglang.org/documentation/0.17.1/#undefined) if any bits that disagree with the resultant sign bit are shifted out.\n\nThe type of `shift_amt` is an unsigned integer with `log2(@typeInfo(T).int.bits)` bits. This is because `shift_amt >= @typeInfo(T).int.bits` triggers safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n`comptime_int` is modeled as an integer with an infinite number of bits, meaning that in such case, `@shlExact` always produces a result and cannot produce a compile error.\n\nSee also: [@shrExact](https://ziglang.org/documentation/0.17.1/#shrExact), [@shlWithOverflow](https://ziglang.org/documentation/0.17.1/#shlWithOverflow)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#shlExact)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#shlExact", .compiler_param_count = 2 },
    .{ .name = "@shlWithOverflow", .signature = "@shlWithOverflow(a: anytype, shift_amt: Log2T) struct { @TypeOf(a), u1 }", .parameters = &.{
        "a: anytype",
        "shift_amt: Log2T",
    }, .documentation = "Performs `a << b` and returns a tuple with the result and a possible overflow bit.\n\nThe type of `shift_amt` is an unsigned integer with `log2(@typeInfo(@TypeOf(a)).int.bits)` bits. This is because `shift_amt >= @typeInfo(@TypeOf(a)).int.bits` triggers safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\nSee also: [@shlExact](https://ziglang.org/documentation/0.17.1/#shlExact), [@shrExact](https://ziglang.org/documentation/0.17.1/#shrExact)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#shlWithOverflow)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#shlWithOverflow", .compiler_param_count = 2 },
    .{ .name = "@shrExact", .signature = "@shrExact(value: T, shift_amt: Log2T) T", .parameters = &.{
        "value: T",
        "shift_amt: Log2T",
    }, .documentation = "Performs the right shift operation (`>>`). Caller guarantees that the shift will not shift any 1 bits out.\n\nThe type of `shift_amt` is an unsigned integer with `log2(@typeInfo(T).int.bits)` bits. This is because `shift_amt >= @typeInfo(T).int.bits` triggers safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\nSee also: [@shlExact](https://ziglang.org/documentation/0.17.1/#shlExact), [@shlWithOverflow](https://ziglang.org/documentation/0.17.1/#shlWithOverflow)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#shrExact)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#shrExact", .compiler_param_count = 2 },
    .{ .name = "@shuffle", .signature = "@shuffle(comptime E: type, a: @Vector(a_len, E), b: @Vector(b_len, E), comptime mask: @Vector(mask_len, i32)) @Vector(mask_len, E)", .parameters = &.{
        "comptime E: type",
        "a: @Vector(a_len, E)",
        "b: @Vector(b_len, E)",
        "comptime mask: @Vector(mask_len, i32)",
    }, .documentation = "Constructs a new [vector](https://ziglang.org/documentation/0.17.1/#Vectors) by selecting elements from `a` and `b` based on `mask`.\n\nEach element in `mask` selects an element from either `a` or `b`. Positive numbers select from `a` starting at 0. Negative values select from `b`, starting at `-1` and going down. It is recommended to use the `~` operator for indexes from `b` so that both indexes can start from `0` (i.e. `~@as(i32, 0)` is `-1`).\n\nFor each element of `mask`, if it or the selected value from `a` or `b` is `undefined`, then the resulting element is `undefined`.\n\n`a_len` and `b_len` may differ in length. Out-of-bounds element indexes in `mask` result in compile errors.\n\nIf `a` or `b` is `undefined`, it is equivalent to a vector of all `undefined` with the same length as the other vector. If both vectors are `undefined`, `@shuffle` returns a vector with all elements `undefined`.\n\n`E` must be an [integer](https://ziglang.org/documentation/0.17.1/#Integers), [float](https://ziglang.org/documentation/0.17.1/#Floats), [pointer](https://ziglang.org/documentation/0.17.1/#Pointers), or `bool`. The mask may be any vector length, and its length determines the result length.\n\nOfficial example: [test\\_shuffle\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#shuffle)\n\nSee also: [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#shuffle)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#shuffle", .compiler_param_count = 4 },
    .{ .name = "@sin", .signature = "@sin(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Sine trigonometric function on a floating point number in radians. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#sin)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#sin", .compiler_param_count = 1 },
    .{ .name = "@sizeOf", .signature = "@sizeOf(comptime T: type) comptime_int", .parameters = &.{
        "comptime T: type",
    }, .documentation = "This function returns the number of bytes it takes to store `T` in memory. The result is a target-specific compile time constant.\n\nThis size may contain padding bytes. If there were two consecutive T in memory, the padding would be the offset in bytes between element at index 0 and the element at index 1. For [integer](https://ziglang.org/documentation/0.17.1/#Integers), consider whether you want to use `@sizeOf(T)` or `@typeInfo(T).int.bits`.\n\nThis function measures the size at runtime. For types that are disallowed at runtime, such as `comptime_int` and `type`, the result is `0`.\n\nSee also: [@bitSizeOf](https://ziglang.org/documentation/0.17.1/#bitSizeOf), [@typeInfo](https://ziglang.org/documentation/0.17.1/#typeInfo)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#sizeOf)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#sizeOf", .compiler_param_count = 1 },
    .{ .name = "@splat", .signature = "@splat(element: anytype) anytype", .parameters = &.{
        "element: anytype",
    }, .documentation = "Produces an array or vector where each element is the value `element`. The return type, including the number of elements, is inferred.\n\nOfficial example: [test\\_splat\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#splat)\n\nSee also: [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors), [Arrays](https://ziglang.org/documentation/0.17.1/#Arrays), [@shuffle](https://ziglang.org/documentation/0.17.1/#shuffle)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#splat)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#splat", .compiler_param_count = 1 },
    .{ .name = "@sqrt", .signature = "@sqrt(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Performs the square root of a floating point number. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#sqrt)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#sqrt", .compiler_param_count = 1 },
    .{ .name = "@src", .signature = "@src() std.lang.SourceLocation", .parameters = &.{}, .documentation = "Returns a `SourceLocation` struct representing the function's name and location in the source code. This must be called in a function.\n\nOfficial example: [test\\_src\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#src)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#src)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#src", .compiler_param_count = 0 },
    .{ .name = "@subWithOverflow", .signature = "@subWithOverflow(a: anytype, b: anytype) struct { @TypeOf(a, b), u1 }", .parameters = &.{
        "a: anytype",
        "b: anytype",
    }, .documentation = "Performs `a - b` and returns a tuple with the result and a possible overflow bit.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#subWithOverflow)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#subWithOverflow", .compiler_param_count = 2 },
    .{ .name = "@tagName", .signature = "@tagName(value: anytype) [:0]const u8", .parameters = &.{
        "value: anytype",
    }, .documentation = "Converts an enum value or union value to a string literal representing the name.\n\nIf the enum is non-exhaustive and the tag value does not map to a name, it invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#tagName)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#tagName", .compiler_param_count = 1 },
    .{ .name = "@tan", .signature = "@tan(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Tangent trigonometric function on a floating point number in radians. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of floats.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#tan)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#tan", .compiler_param_count = 1 },
    .{ .name = "@trap", .signature = "@trap() noreturn", .parameters = &.{}, .documentation = "This function inserts a platform-specific trap/jam instruction which can be used to exit the program abnormally. This may be implemented by explicitly emitting an invalid instruction which may cause an illegal instruction exception of some sort. Unlike for `@breakpoint()`, execution does not continue after this point.\n\nOutside function scope, this builtin causes a compile error.\n\nSee also: [@breakpoint](https://ziglang.org/documentation/0.17.1/#breakpoint)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#trap)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#trap", .compiler_param_count = 0 },
    .{ .name = "@trunc", .signature = "@trunc(value: anytype) @TypeOf(value)", .parameters = &.{
        "value: anytype",
    }, .documentation = "Rounds the given floating point number to an integer, towards zero. Uses a dedicated hardware instruction when available.\n\nSupports [Floats](https://ziglang.org/documentation/0.17.1/#Floats) and [Vectors](https://ziglang.org/documentation/0.17.1/#Vectors) of float parameters.\n\nWhen the inferred result type is an [integer](https://ziglang.org/documentation/0.17.1/#Integers), the integer part is extracted from the truncated result. If that value cannot fit in the destination type, it invokes safety-checked [Illegal Behavior](https://ziglang.org/documentation/0.17.1/#Illegal-Behavior).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#trunc)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#trunc", .compiler_param_count = 1 },
    .{ .name = "@truncate", .signature = "@truncate(integer: anytype) anytype", .parameters = &.{
        "integer: anytype",
    }, .documentation = "This function truncates bits from an integer type, resulting in a smaller or same-sized integer type. The return type is the inferred result type.\n\nThis function always truncates the significant bits of the integer, regardless of endianness on the target platform.\n\nCalling `@truncate` on a number out of range of the destination type is well defined and working code:\n\nOfficial example: [test\\_truncate\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#truncate)\n\nUse [@intCast](https://ziglang.org/documentation/0.17.1/#intCast) to convert numbers guaranteed to fit the destination type.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#truncate)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#truncate", .compiler_param_count = 1 },
    .{ .name = "@typeInfo", .signature = "@typeInfo(comptime T: type) std.lang.Type", .parameters = &.{
        "comptime T: type",
    }, .documentation = "Provides type reflection.\n\nType information of [structs](https://ziglang.org/documentation/0.17.1/#struct), [unions](https://ziglang.org/documentation/0.17.1/#union), [enums](https://ziglang.org/documentation/0.17.1/#enum), and [error sets](https://ziglang.org/documentation/0.17.1/#Error-Set-Type) has fields which are guaranteed to be in the same order as appearance in the source file.\n\nType information of [structs](https://ziglang.org/documentation/0.17.1/#struct), [unions](https://ziglang.org/documentation/0.17.1/#union), [enums](https://ziglang.org/documentation/0.17.1/#enum), and [opaques](https://ziglang.org/documentation/0.17.1/#opaque) has declarations, which are also guaranteed to be in the same order as appearance in the source file.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#typeInfo)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#typeInfo", .compiler_param_count = 1 },
    .{ .name = "@typeName", .signature = "@typeName(T: type) *const [N:0]u8", .parameters = &.{
        "T: type",
    }, .documentation = "This function returns the string representation of a type, as an array. It is equivalent to a string literal of the type name. The returned type name is fully qualified with the parent namespace included as part of the type name with a series of dots.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#typeName)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#typeName", .compiler_param_count = 1 },
    .{ .name = "@unionInit", .signature = "@unionInit(comptime Union: type, comptime active_field_name: []const u8, init_expr) Union", .parameters = &.{
        "comptime Union: type",
        "comptime active_field_name: []const u8",
        "init_expr",
    }, .documentation = "This is the same thing as [union](https://ziglang.org/documentation/0.17.1/#union) initialization syntax, except that the field name is a [comptime](https://ziglang.org/documentation/0.17.1/#comptime)-known value rather than an identifier token.\n\n`@unionInit` forwards its [result location](https://ziglang.org/documentation/0.17.1/#Result-Location-Semantics) to `init_expr`.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#unionInit)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#unionInit", .compiler_param_count = 3 },
    .{ .name = "@volatileCast", .signature = "@volatileCast(value: anytype) DestType", .parameters = &.{
        "value: anytype",
    }, .documentation = "Remove `volatile` qualifier from a pointer.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#volatileCast)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#volatileCast", .compiler_param_count = 1 },
    .{ .name = "@wasmMemoryGrow", .signature = "@wasmMemoryGrow(index: u32, delta: usize) isize", .parameters = &.{
        "index: u32",
        "delta: usize",
    }, .documentation = "This function increases the size of the Wasm memory identified by `index` by `delta` in units of unsigned number of Wasm pages. Note that each Wasm page is 64KB in size. On success, returns previous memory size; on failure, if the allocation fails, returns -1.\n\nThis function is a low level intrinsic with no safety mechanisms usually useful for allocator designers targeting Wasm. So unless you are writing a new allocator from scratch, you should use something like `@import(\"std\").heap.WasmPageAllocator`.\n\nOfficial example: [test\\_wasmMemoryGrow\\_builtin.zig](https://ziglang.org/documentation/0.17.1/#wasmMemoryGrow)\n\nSee also: [@wasmMemorySize](https://ziglang.org/documentation/0.17.1/#wasmMemorySize)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#wasmMemoryGrow)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#wasmMemoryGrow", .compiler_param_count = 2 },
    .{ .name = "@wasmMemorySize", .signature = "@wasmMemorySize(index: u32) usize", .parameters = &.{
        "index: u32",
    }, .documentation = "This function returns the size of the Wasm memory identified by `index` as an unsigned value in units of Wasm pages. Note that each Wasm page is 64KB in size.\n\nThis function is a low level intrinsic with no safety mechanisms usually useful for allocator designers targeting Wasm. So unless you are writing a new allocator from scratch, you should use something like `@import(\"std\").heap.WasmPageAllocator`.\n\nSee also: [@wasmMemoryGrow](https://ziglang.org/documentation/0.17.1/#wasmMemoryGrow)\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#wasmMemorySize)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#wasmMemorySize", .compiler_param_count = 1 },
    .{ .name = "@workGroupId", .signature = "@workGroupId(comptime dimension: u32) u32", .parameters = &.{
        "comptime dimension: u32",
    }, .documentation = "Returns the index of the work group in the current kernel invocation in dimension `dimension`.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#workGroupId)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#workGroupId", .compiler_param_count = 1 },
    .{ .name = "@workGroupSize", .signature = "@workGroupSize(comptime dimension: u32) u32", .parameters = &.{
        "comptime dimension: u32",
    }, .documentation = "Returns the number of work items that a work group has in dimension `dimension`.\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#workGroupSize)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#workGroupSize", .compiler_param_count = 1 },
    .{ .name = "@workItemId", .signature = "@workItemId(comptime dimension: u32) u32", .parameters = &.{
        "comptime dimension: u32",
    }, .documentation = "Returns the index of the work item in the work group in dimension `dimension`. This function returns values between `0` (inclusive) and `@workGroupSize(dimension)` (exclusive).\n\n[Zig 0.17.1 Language Reference](https://ziglang.org/documentation/0.17.1/#workItemId)", .variadic = false, .documented = true, .source_url = "https://ziglang.org/documentation/0.17.1/#workItemId", .compiler_param_count = 1 },
};
